{
  "aktywnosci": [
    {
      "tytul": "Leśne skarby – sensoryczne pudełko",
      "opis": "Nauczyciel przygotowuje pudełko wypełnione darami jesieni: szyszkami, żołędziami, kasztanami, suchymi liśćmi i kawałkami kory. Dzieci po kolei wkładają rękę do pudełka, dotykają i odgadują, co znalazły. Potem wspólnie oglądają skarby, nazywają je i układają według wielkości lub koloru."
    },
    {
      "tytul": "Wiewiórka zbiera orzechy – zabawa ruchowa",
      "opis": "Nauczyciel rozrzuca na dywanie orzechy włoskie (lub kasztany) i ustawia kilka obręczy jako „dziuple”. Dzieci wcielają się w wiewiórki i na sygnał zbierają po jednym orzechu, przenosząc go do dowolnej dziupli. Zabawa powtarza się kilka razy, a na koniec każde dziecko liczy, ile orzechów udało mu się zgromadzić."
    },
    {
      "tytul": "Jesienne drzewo – praca plastyczna",
      "opis": "Na dużym arkuszu szarego papieru nauczyciel rysuje kontur drzewa bez liści. Dzieci odciskają na kartkach dłonie pomalowane farbą w odcieniach czerwieni, pomarańczu i żółci, a następnie wycinają odbite liście i przyklejają je do gałęzi. Powstaje wspólne, kolorowe jesienne drzewo."
    }
  ]
}
